Hi! That sounds fun. I can help you build it so you can play.

Here is a tiny game you can copy into a file and play in a browser.

1. Open a plain text app.
2. Copy this code.
3. Save it as `cat-fish-game.html`
4. Open the file.

```html
<!DOCTYPE html>
<html>
<head>
  <title>Cat Catches Fish</title>
  <style>
    body {
      margin: 0;
      text-align: center;
      font-family: Arial;
      background: skyblue;
    }

    canvas {
      background: linear-gradient(skyblue, lightblue);
      border: 4px solid #333;
      margin-top: 20px;
    }
  </style>
</head>
<body>
  <h1>Cat Catches Fish</h1>
  <p>Use the left and right arrow keys to move the cat.</p>
  <canvas id="game" width="500" height="400"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    let cat = {
      x: 220,
      y: 340,
      width: 60,
      height: 40,
      speed: 6
    };

    let fish = {
      x: Math.random() * 470,
      y: 0,
      width: 30,
      height: 20,
      speed: 3
    };

    let score = 0;
    let lives = 3;
    let leftPressed = false;
    let rightPressed = false;

    document.addEventListener("keydown", function(event) {
      if (event.key === "ArrowLeft") leftPressed = true;
      if (event.key === "ArrowRight") rightPressed = true;
    });

    document.addEventListener("keyup", function(event) {
      if (event.key === "ArrowLeft") leftPressed = false;
      if (event.key === "ArrowRight") rightPressed = false;
    });

    function drawCat() {
      ctx.font = "40px Arial";
      ctx.fillText("🐱", cat.x, cat.y + 35);
    }

    function drawFish() {
      ctx.font = "28px Arial";
      ctx.fillText("🐟", fish.x, fish.y + 25);
    }

    function drawScore() {
      ctx.fillStyle = "black";
      ctx.font = "20px Arial";
      ctx.fillText("Score: " + score, 10, 25);
      ctx.fillText("Lives: " + lives, 400, 25);
    }

    function resetFish() {
      fish.x = Math.random() * 470;
      fish.y = 0;
    }

    function update() {
      if (leftPressed && cat.x > 0) {
        cat.x -= cat.speed;
      }

      if (rightPressed && cat.x < canvas.width - cat.width) {
        cat.x += cat.speed;
      }

      fish.y += fish.speed;

      // Check if cat catches fish
      if (
        fish.x < cat.x + cat.width &&
        fish.x + fish.width > cat.x &&
        fish.y < cat.y + cat.height &&
        fish.y + fish.height > cat.y
      ) {
        score++;
        fish.speed += 0.3;
        resetFish();
      }

      // Fish missed
      if (fish.y > canvas.height) {
        lives--;
        resetFish();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawScore();
      drawFish();
      drawCat();

      if (lives <= 0) {
        ctx.fillStyle = "black";
        ctx.font = "35px Arial";
        ctx.fillText("Game Over!", 150, 190);
        ctx.font = "22px Arial";
        ctx.fillText("Refresh to play again", 155, 230);
        return;
      }

      update();
      requestAnimationFrame(draw);
    }

    draw();
  </script>
</body>
</html>
```

Try playing it. Then you can change one thing yourself.

A good first change: find this line:

```js
fish.speed += 0.3;
```

Make `0.3` bigger if you want the game to get harder faster. What do you want to add next?

